assert len(D)==25 and {a[0] for a in D}=={s['shot_id'] for s in shots}
S={s['shot_id']:s for s in shots}
headers=['shot_id','illusion_id','illusion_zh','category','reference_artist','reference_work','reference_year','source_url','mapping_strength','source_mechanism','j4_original_transformation','execution_method','do_not_copy','acceptance_test']
rows=[]
for d in D:
 r=dict(zip(headers,d)); assert r['illusion_id']==S[r['shot_id']]['illusion_type']
 r['source_status']='PRIMARY_OR_INSTITUTIONAL_VERIFIED'
 r['original_art_reference']=S[r['shot_id']]['original_art_reference']
 r['first_read']=S[r['shot_id']]['first_read'];r['second_read']=S[r['shot_id']]['second_read']
 r['asset_ids']=S[r['shot_id']]['all_swappable_slots']
 r['memory_arc_ids']=S[r['shot_id']]['memory_arcs']
 r['effect_status']='DESIGN_ONLY';r['viewer_test']='NOT_RUN';r['image_test']='NOT_RUN';r['audio_test']='NOT_RUN';r['rights_review']='NOT_RUN';r['director_approval']='NOT_RUN'
 r['prompt_delta_en']=(f"OPTICAL CONTRACT {r['shot_id']} / {r['illusion_id']}: "
                      f"Create an ORIGINAL fictional material scene that uses {r['execution_method']}. "
                      f"The first reading is: {r['first_read']}. On a second viewing reveal: {r['second_read']}. "
                      f"Reference {r['reference_artist']}'s {r['reference_work']} only for the general perceptual principle, "
                      f"never reproduce its object geometry, distinctive installation layout, audiovisual material or recognizable imagery. "
                      f"Forbidden: {r['do_not_copy']}. Keep physical identity locks and comply with the shot's existing generation gate.")
 rows.append(r)
md=[]
md.append('# J4 v3.3 — 每鏡錯視 × 可核對的當代藝術對標\n')
md.append('**Design-only / 0 generation.** 這是 v3.2 的非破壞性增量修訂。每個藝術錯視都有一個來源；但「方法類比」不宣稱原作實際使用完全相同機制。\n')
md.append('## 三類不同機制\n- **PERCEPTUAL**：實際形狀、深度、圖地或光影知覺的歧義。\n- **TEMPORAL_AUDIOVISUAL**：聲畫不同步或聲源歸屬錯位。\n- **NARRATIVE_RECONTEXT**：後一鏡改寫前一鏡意義；不是嚴格意義的視覺錯視。\n')
md.append('## 25 鏡完整表\n')
md.append('| 鏡 | 知覺／時間方法 | 藝術對標（新增的錯視參考） | J4 原創轉譯 | 證據關係 |\n|---|---|---|---|---|')
for r in rows:
 md.append(f"| {r['shot_id']} | {r['illusion_zh']} | [{r['reference_artist']} — {r['reference_work']}（{r['reference_year']}）]({r['source_url']}) | {r['j4_original_transformation']} | {r['mapping_strength']} |")
md.append('\n## 三個優先驗證的記憶召喚\n')
md.append('### A. S10 → S21：真假外套（物件身分＋圖地反轉）\n- **先見結果**：S10 的檔案外套 B 被收納，看起來像創造者衣物。\n- **後來重解**：S21 主線外套 A 左下襬補丁可見；B 沒有。\n- **光學證據**：S10 布料+網格影子看似人物，但回到物件本體仍是空外套。\n- **藝術錨點**：Tim Noble × Sue Webster《Dirty White Trash (with Gulls)》（MoMA）；Pistoletto《Man with Yellow Pants》（MoMA）。\n- **測試**：首看先誤認 B、後看能用補丁辨 A/B；不讓任何人誤認為真人肖像。\n')
md.append('### B. S11 → S22：紙屋尺度重讀（物件材質＋模型現實）\n- **先見結果**：工廠中微小紙屋是人的生活痕跡。\n- **後來重解**：上班族在空樓層摺出整座無人居住的紙海岸。\n- **藝術錨點**：Liliana Porter《Untitled (with Cube – tall)》（Whitney）；Thomas Demand《Office》（Guggenheim）。\n- **測試**：3 秒正常速度下第一影格同時能辨人物／紙橋／空屋，且摺痕與手的尺度足以證明是紙。\n')
md.append('### C. S18 → S19：光形回望（形態先現、語義後到）\n- **先見結果**：三個低亮抽象光體只像訊號。\n- **後來重解**：S19 三個核心座位受光照，讓前鏡形狀具有權力配置意義。\n- **藝術錨點**：Jim Campbell《Exploded Views》（SFMOMA）；James Turrell《Afrum I (White)》（Guggenheim）。\n- **測試**：先播放 S18 不劇透，再播放 S18+S19；第二次觀看辨認三處光位而非識別任何政治人物。\n')
md.append('## 五道驗收 Gate\n1. **Source Gate**：作品名稱／年代／機制／機構或藝術家連結都有依據。\n2. **Mechanism Gate**：物理錯視必須可計算/可重播；敘事類不得冒稱光學效果。\n3. **Identity Gate**：交換任一物件須保留物件狀態與跨鏡 invariant。\n4. **Blind Audience Gate**：先看單鏡，再看揭示鏡，收集第一讀法與第二讀法；未測者 NOT_RUN。\n5. **Rights Gate**：不得複製參考作品獨特造型、錄音、表演或具辨識度的裝置結構。\n\n本資料不變更 90 秒時間軸、S18 63.700 秒聲音中斷、授權 BLOCKED 狀態。')
(out/'ART_ILLUSION_REFERENCE_BIBLE_v3_3.md').write_text('\n'.join(md),encoding='utf-8')
