page='''<!doctype html><html lang="zh-Hant"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>J4 v3.3 | Art Illusion Evidence Board</title><style>:root{color-scheme:dark}body{background:#0c1119;color:#eef1f4;font:16px/1.58 -apple-system,BlinkMacSystemFont,"Noto Sans TC",sans-serif;margin:0}.wrap{max-width:1120px;margin:auto;padding:28px 20px}h1{font-size:28px;letter-spacing:-.03em}p{color:#aab4c2}select{background:#172333;border:1px solid #33475c;border-radius:9px;color:white;padding:12px;max-width:100%}.top{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}article,.note{background:#121c29;border:1px solid #2b394a;border-radius:14px;padding:20px;margin:16px 0}h2{margin:0 0 10px;font-size:24px}h3{font-size:15px;color:#bac7d3;margin:18px 0 4px}span.tag{border:1px solid #465d71;border-radius:18px;color:#b4d5e7;padding:3px 9px;font-size:12px}a{color:#9dd4ff;word-break:break-all}.two{display:grid;grid-template-columns:1fr 1fr;gap:18px}.mono{font-family:ui-monospace,monospace;color:#e6f3fc;white-space:pre-wrap;font-size:13px}button{background:#23364a;border:1px solid #53677a;color:#fff;padding:9px 13px;border-radius:8px;cursor:pointer}footer{color:#93a3b2;margin-top:28px} @media(max-width:680px){.two{grid-template-columns:1fr}.wrap{padding:16px}}</style></head><body><main class="wrap"><h1>J4 · v3.3 當代藝術錯視證據板</h1><p>25 / 25 鏡各有藝術對標。作品核對不代表藝術審核通過；此頁沒有影片、付費生成或內容上傳。</p><div class="top"><label>鏡頭 <select id="shot"></select></label><label>類型 <select id="filter"><option value="ALL">全部</option><option value="PERCEPTUAL">知覺錯視</option><option value="TEMPORAL_AUDIOVISUAL">聲畫／時間</option><option value="NARRATIVE_RECONTEXT">敘事重釋</option></select></label></div><article id="detail"></article><div class="note"><h3>審核提醒</h3><p>先看原始單鏡，記錄第一種讀法；再播放揭示鏡，記錄第二種讀法。源作品只能參考知覺方法，不能複製圖像、裝置佈局與原聲。所有影像和觀眾測試為 NOT_RUN。</p><button id="copy">複製目前 Prompt Delta</button></div><footer>DESIGN-ONLY · All paid generation gates BLOCKED · 90.000s / 30 fps unchanged</footer></main><script>const data=__DATA__;const select=document.getElementById('shot'),f=document.getElementById('filter'),target=document.getElementById('detail');let current=data[0];function el(tag,text){const x=document.createElement(tag);x.textContent=text;return x;}function line(label,val){target.appendChild(el('h3',label));target.appendChild(el('div',val));}function draw(){current=data.find(x=>x.shot_id===select.value)||data[0];target.replaceChildren();target.appendChild(el('h2',current.shot_id+' · '+current.illusion_zh));target.appendChild(el('span',current.category+' / '+current.mapping_strength));line('藝術對標',current.reference_artist+' — '+current.reference_work+' ('+current.reference_year+')');let a=el('a','核對藝術作品來源');a.href=current.source_url;a.target='_blank';a.rel='noopener noreferrer';target.appendChild(a);line('來源作品實際機制',current.source_mechanism);line('第一眼',current.first_read);line('再次觀看',current.second_read);line('J4 原創改寫',current.j4_original_transformation);line('鏡頭實作',current.execution_method);line('不可複製',current.do_not_copy);line('驗收',current.acceptance_test);target.appendChild(el('h3','Prompt Delta'));const p=el('div',current.prompt_delta_en);p.className='mono';target.appendChild(p)}function populate(){let old=select.value;select.replaceChildren();data.filter(x=>f.value==='ALL'||x.category===f.value).forEach(x=>{let o=el('option',x.shot_id+' — '+x.illusion_zh);o.value=x.shot_id;select.appendChild(o)});if([...select.options].some(o=>o.value===old))select.value=old;draw()}select.addEventListener('change',draw);f.addEventListener('change',populate);document.getElementById('copy').addEventListener('click',()=>{if(navigator.clipboard)navigator.clipboard.writeText(current.prompt_delta_en)});populate();</script></body></html>'''.replace('__DATA__',JS)
